-- Sanity checks (optional)
-- -------------------------------------------
SELECT 'lecturers' AS check_name, @lec1_id AS lec1_id, @lec2_id AS lec2_id;
SELECT c.class_code, sem.semester_code, sub.subject_code, u.username AS lecturer, COUNT(DISTINCT cs.student_id) AS enrolled, COUNT(DISTINCT g.id) AS teams FROM classes c JOIN semesters sem ON sem.id = c.semester_id JOIN subjects sub ON sub.id = c.subject_id LEFT JOIN users u ON u.id = c.lecturer_id LEFT JOIN class_students cs ON cs.class_id = c.id LEFT JOIN `groups` g ON g.class_id = c.id AND g.deleted_at IS NULL WHERE c.class_code IN ('DE18FA01','DE18FA02','DE18SP01','DE18SU01') GROUP BY c.id, c.class_code, sem.semester_code, sub.subject_code, u.username ORDER BY sem.semester_code, c.class_code;

